"""Explain USB/DMA direction and page-boundary processing for beginners."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1817': ('USB 장치에 물건을 보내기 전에는 내용이 준비됐는지 확인하고, 장치에서 들어온 내용에는 받았다는 검사 표시를 붙여요.', 'USB 요청의 입력·출력 방향별 검사 동작을 이해합니다.', '12바이트 요청에서 OUT은 검사, IN은 준비됨 표시로 두 화살표를 그리세요.', ['URB는 USB 전송 요청을 담는 구조예요. transfer_buffer는 전송용 메모리 주소이고 transfer_buffer_length는 그 범위의 길이예요. kmsan_handle_urb는 이 정보를 보고 검사 처리를 선택해요.', 'urb 자체가 NULL이면 요청 구조가 없으므로 돌아가요. 이 함수 본문에는 별도의 kmsan_enabled나 kmsan_in_runtime 검사가 없어요. 다른 hook의 조건을 여기에도 있다고 가정하지 말고 호출자의 역할까지 따로 살펴야 해요.', 'is_out이 참이면 컴퓨터에서 장치로 나가는 방향이에요. 도우미는 buffer의 준비 상태를 check_memory로 검사하고 이유에 REASON_SUBMIT_URB를 넣어요. 의도하지 않은 미준비 내용이 장치로 나가는지 확인하는 일이에요.', 'is_out이 거짓이면 반대 방향으로 보고 unpoison을 호출해요. unpoison은 검사표를 준비됨 상태로 바꾸는 것이며 checked에는 false를 전달해요. 이 함수가 USB 장치에서 데이터를 직접 받아 쓰는 것은 아니에요.', '길이가 12라면 두 분기 모두 transfer_buffer_length의 12를 사용해요. 함수가 별도의 실제 수신 길이를 계산하는 코드는 없어요. 실제로 장치가 언제 몇 바이트를 채웠는지와 호출 시점은 USB 전송 경로에서 함께 확인해야 해요.', '따라서 입력 분기의 준비됨 표시만으로 전송 완료나 내용의 정확성이 증명되지는 않아요. 이 수업에서는 요청 구조에 있는 주소·길이·방향이 검사 함수로 어떻게 전달되는지 따라가요.'], [('USB 출력 방향에서 이 도우미는 무엇을 하나요?', ['미준비 표시를 무조건 지우고 안전하다고 처리해요', '장치로 보낼 buffer의 준비 상태를 검사해요'], '정답은 두 번째예요. is_out 분기는 check_memory를 호출해요. 반대 방향의 unpoison과 역할이 달라요.'), ('이 URB 도우미 본문에 enabled와 runtime 조기 반환 조건이 있나요?', ['아니요. 요청 NULL 확인과 방향 분기가 있어요', '네. 다른 hook와 똑같은 조건이 모두 있어요'], '정답은 첫 번째예요. 본문에 없는 조건을 보태 읽으면 안 돼요. 필요한 호출 조건은 호출하는 쪽과 내부 함수까지 연결해서 살펴야 해요.')]), 'os1818': ('보내는 짐의 내용을 확인하기 전에 검사표부터 지우면 원래 문제가 있었는지 놓칠 수 있어요. 양방향 처리에서는 순서가 중요해요.', 'DMA 네 방향의 검사와 준비됨 표시 순서를 이해합니다.', 'TO는 검사, FROM은 표시, BOTH는 검사→표시, NONE은 없음으로 네 줄을 적으세요.', ['DMA는 장치와 메모리 사이의 데이터 이동을 지원하는 방식이에요. 이 함수는 실제 전송 장치를 조작하기보다 방향에 맞춰 KMSAN 검사 정보를 처리해요. dir라는 인자로 방향을 받아 switch로 나눠요.', 'DMA_TO_DEVICE는 메모리에서 장치로 나가는 방향이에요. check_memory를 호출해 보낼 범위의 준비 상태를 검사해요. 이 호출의 이유 표시는 REASON_ANY예요.', 'DMA_FROM_DEVICE는 장치에서 메모리로 들어오는 방향이에요. checked false로 unpoison을 호출해 준비됨 표시를 요청해요. 실제 장치가 데이터를 쓴 시점이나 전송 완료 여부를 이 함수가 확인하는 코드는 아니에요.', 'DMA_BIDIRECTIONAL은 양방향이에요. 원문은 먼저 검사한 뒤 unpoison해요. 반대로 준비됨 표시부터 하면 이전의 미준비 상태를 지워 검사에서 놓칠 수 있으므로 두 호출의 순서를 그대로 읽어야 해요.', 'DMA_NONE은 이 helper에서 아무 호출 없이 break로 끝나요. 따라서 TO, FROM, BOTH, NONE의 검사·표시 호출 수는 각각 1, 1, 2, 0이에요. NONE이 전체 DMA 사용법에서 항상 올바른 선택이라는 뜻은 아니에요.', '캐시 일관성은 CPU와 장치가 보는 내용이 맞도록 하는 문제이고 전송 완료는 장치 작업이 끝났는지의 문제예요. 이 함수의 검사표 정책만으로 그런 동기화까지 처리했다고 보면 안 돼요. 실제 전송 계약은 상위 호출 흐름에서 확인해요.'], [('양방향 DMA 분기의 두 처리는 어떤 순서인가요?', ['준비됨 표시를 먼저 하고 검사해요', '먼저 검사하고 준비됨 표시를 해요'], '정답은 두 번째예요. check_memory 다음 unpoison이에요. 검사 전에 상태를 지워 버리면 기존 미준비 여부를 놓칠 수 있어요.'), ('DMA_NONE에서 이 helper가 추가하는 검사·표시 호출은 몇 번인가요?', ['0번이에요', '반드시 검사 두 번이에요'], '정답은 첫 번째예요. 해당 case에는 break만 있어요. 방향 이름과 실제 호출 개수를 연결해 읽으세요.')]), 'os1819': ('일반 통로로 바로 갈 수 없는 창고는 이 도우미가 건너뛰어요. 처리할 수 있는 창고에서는 첫 칸이 아니라 지정한 위치부터 시작해요.', 'highmem 조기 반환과 페이지 시작에 offset을 더하는 계산을 이해합니다.', '페이지 시작 8192, offset 100이면 시작 주소 8292를 적고 highmem일 때는 계산 전 반환에 표시하세요.', ['kmsan_handle_dma는 페이지와 그 안에서 시작할 위치, 처리 길이, 전송 방향을 받아요. 페이지는 메모리 덩어리이고 offset은 기준 주소에서 얼마나 떨어졌는지를 나타내요.', '첫 조건은 PageHighMem(page)예요. highmem은 이 경로에서 쓰는 일반적인 직접 주소로 다루기 어려운 높은 메모리 페이지를 구분하는 개념이에요. 조건이 참이면 곧바로 돌아가요.', '이 함수에는 highmem을 위한 임시 mapping을 만드는 코드가 없어요. 따라서 모든 페이지를 자동으로 검사한다거나 highmem도 알아서 연결한 뒤 처리한다고 설명하면 원문에 없는 작업을 추가하는 셈이에요.', '그 외에는 page_address(page)로 얻은 주소에 offset을 더해 addr를 구해요. 페이지 시작이 8192이고 offset이 100이면 8292부터 처리해요. offset이 있는데도 언제나 페이지 첫 주소부터 시작하는 것은 아니에요.', '그다음 반복문은 실제 addr가 페이지 안에서 어디에 있는지 offset_in_page로 다시 계산해요. 이는 다음 경계까지 얼마를 처리할지 정하는 데 쓰여요. 호출 인자의 offset과 매 반복의 페이지 내 위치는 역할을 구분해서 읽어요.', '이 계산은 유효한 페이지와 주소 범위를 호출자가 제공한다는 전제예요. 숫자 예시로 주소 계산을 확인한 것은 실제 highmem 임시 연결이나 모든 기종의 page_address 동작을 실행한 실험과 달라요.'], [('이 helper는 highmem 페이지를 직접 임시 연결해서 검사하나요?', ['네. 어떤 페이지든 반드시 임시 연결해요', '아니요. PageHighMem 조건에서 돌아가요'], '정답은 두 번째예요. 첫 조건 뒤에 return이 있어요. 함수 안에 없는 임시 mapping 동작을 추측해 넣지 마세요.'), ('일반 경로의 첫 처리 주소는 어떻게 구하나요?', ['page_address(page)에 offset을 더해요', 'offset을 무시하고 항상 page_address(page)만 써요'], '정답은 첫 번째예요. 실제 대입문에 + offset이 있어요. 8192 + 100 = 8292처럼 시작점을 계산해 보세요.')]), 'os1820': ('책 두 쪽에 걸친 문장을 읽을 때 첫 쪽의 남은 부분부터 읽고 다음 쪽으로 넘어가요. 메모리 검사도 페이지 경계에서 나누어 처리해요.', '페이지 경계별 처리량과 반복 종료를 계산합니다.', '페이지 크기 4096, 시작 위치 4092, 길이 12에서 첫 4바이트와 다음 8바이트를 그리세요.', ['DMA 범위의 이웃한 페이지들이 서로 다른 할당에서 왔을 수 있어요. 데이터가 이어져 보여도 검사 정보까지 이어진다고 가정할 수 없어서 원문은 페이지마다 나눠 처리한다고 설명해요.', 'while (size > 0)은 아직 처리할 길이가 있을 때 반복한다는 뜻이에요. 각 반복은 offset_in_page(addr)로 현재 페이지 안 위치를 구해요. 페이지 크기에서 그 위치를 빼면 이번 페이지에 남은 바이트 수가 돼요.', '그 수와 전체 남은 size 중 작은 값을 min으로 골라 to_go에 넣어요. to_go는 이번에 처리할 길이예요. 페이지 밖으로 나가지 않으면서 요청 범위도 넘지 않도록 두 제한을 함께 적용해요.', '페이지가 4096바이트이고 현재 위치가 4092면 끝까지 4바이트예요. 남은 요청 12와 비교해 작은 4를 처리해요. addr는 4 늘어나 다음 페이지 시작으로 가고 size는 12 - 4 = 8이 돼요.', '다음 반복은 페이지 안 위치 0이라 4096바이트가 남지만 요청은 8뿐이에요. 그래서 8을 처리하고 size는 0이 돼요. 다음 while 조건이 거짓이라 끝나요. 처리 길이 합은 4 + 8 = 12로 원래 요청과 같아요.', '유효한 주소 범위에서 남은 size가 양수이면 to_go도 양수라 반복마다 남은 양이 줄어요. 주소는 늘고 남은 길이는 줄어야 한다는 관계를 함께 확인하세요. 이 계산은 임의의 잘못된 주소나 넘치는 정수 범위까지 안전하다고 증명하는 것은 아니에요.'], [('페이지 크기 4096, 시작 위치 4092, 길이 12라면 어떻게 나누나요?', ['무조건 12바이트를 한 번에 처리해요', '현재 페이지 4바이트와 다음 페이지 8바이트로 나눠요'], '정답은 두 번째예요. 4096 - 4092 = 4예요. 첫 4를 처리하면 8이 남고 다음 페이지에서 그 8을 처리해요.'), ('처리 뒤 남은 길이를 줄이는 식은 무엇인가요?', ['size -= to_go예요', 'size += PAGE_SIZE예요'], '정답은 첫 번째예요. 처리한 만큼 빼야 언젠가 0에 도달해요. 주소를 늘리는 addr += to_go와 짝지어 읽으세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_450.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
